import utils.xz.XzDecoder
import kotlin.io.encoding.Base64
import kotlin.test.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/** Vectors encoded by liblzma (Python lzma); D's plain form is regenerated in [structuredData]. */
class XzDecoderTest {

    private val aPlain = "" +
        ""
    private val aXz = ""
    private val bXz = ""
    private val eXz = ""
    private val cPlain = "" +
        ""
    private val cXz = "" +
        ""
    private val dXz = "" +
        "" +
        "" +
        ""

    private fun b64(s: String): ByteArray = Base64.decode(s)

    /** 5 MiB of structured data, identical to the Python generator's. */
    private fun structuredData(): ByteArray {
        val out = ByteArray(5 * 1024 * 1024)
        for (i in out.indices) {
            out[i] = if (i % 997 == 0) (i and 0xFF).toByte() else ((i shr 10) and 0xFF).toByte()
        }
        return out
    }

    @Test
    fun decodesCrc32Stream() {
        assertContentEquals(b64(aPlain), XzDecoder.decode(b64(aXz)))
    }

    @Test
    fun decodesCrc64ExtremePresetStream() {
        assertContentEquals(b64(aPlain), XzDecoder.decode(b64(bXz)))
    }

    @Test
    fun decodesNoCheckStream() {
        assertContentEquals(b64(aPlain), XzDecoder.decode(b64(eXz)))
    }

    @Test
    fun decodesUncompressedChunks() {
        // Incompressible data at preset 0 forces LZMA2 uncompressed chunks.
        assertContentEquals(b64(cPlain), XzDecoder.decode(b64(cXz)))
    }

    @Test
    fun decodesMultiChunkStream() {
        // 5 MiB unpacked spans multiple LZMA2 chunks (2 MiB max each).
        assertContentEquals(structuredData(), XzDecoder.decode(b64(dXz)))
    }

    @Test
    fun stopsAtMaxOutput() {
        val expected = b64(aPlain).copyOf(100)
        assertContentEquals(expected, XzDecoder.decode(b64(aXz), maxOutput = 100))
    }

    @Test
    fun decodesTruncatedPrefix() {
        // Cutting the compressed stream mid-way still yields the chunks that
        // arrived whole, and their content matches the original's prefix.
        val truncated = b64(dXz).copyOf(8 * 1024)
        val out = XzDecoder.decode(truncated, allowTruncated = true)
        assertTrue(out.isNotEmpty(), "expected at least one whole chunk")
        assertContentEquals(structuredData().copyOf(out.size), out)
    }

    @Test
    fun rejectsGarbage() {
        val garbage = ByteArray(64) { (it * 37).toByte() }
        var failed = false
        try {
            XzDecoder.decode(garbage)
        } catch (_: Exception) {
            failed = true
        }
        assertTrue(failed, "garbage input must not decode")
    }

    @Test
    fun maxOutputLargerThanStreamIsHarmless() {
        assertEquals(b64(aPlain).size, XzDecoder.decode(b64(aXz), maxOutput = 1 shl 30).size)
    }
}
